import json, time, urllib.request, urllib.error, sys
from datetime import datetime, timezone
from collections import defaultdict
B="http://localhost:8080"
tok=None
log=defaultdict(int)
def newtok():
    global tok
    r=urllib.request.Request(B+"/token",method="POST",data=b"")
    tok=json.load(urllib.request.urlopen(r))["token"]
def get(path):
    global tok
    for attempt in range(200):
        if tok is None: newtok()
        req=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok})
        try:
            with urllib.request.urlopen(req,timeout=30) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            body=e.read().decode(errors="replace")
            log[e.code]+=1
            if e.code==404: return None
            if e.code==401: newtok(); continue
            if e.code==429:
                ra=e.headers.get("Retry-After")
                try: w=float(ra)
                except: 
                    try: w=float(json.loads(body).get("retry_after"))
                    except: w=2
                print("429",ra,body[:200],file=sys.stderr)
                time.sleep(w+0.1); continue
            print("ERR",e.code,path,body[:200],file=sys.stderr)
            time.sleep(1)
        except Exception as ex:
            log["exc"]+=1; print("EXC",ex,file=sys.stderr); time.sleep(1)
    raise SystemExit("gave up "+path)
orders=[];page=1;total=None
while True:
    d=get(f"/orders?page={page}")
    total=d["total_pages"]; orders+=d["items"]
    if not d["next"]: break
    page+=1
print("pages",page,"total_pages",total,"rows",len(orders),dict(log),file=sys.stderr)
seen={};dups=0
for o in orders:
    if o["id"] in seen:
        dups+=1
        if seen[o["id"]]!=o: print("DUP DIFFERS",o,seen[o["id"]],file=sys.stderr)
    else: seen[o["id"]]=o
lo=datetime(2025,3,1,tzinfo=timezone.utc); hi=datetime(2025,6,1,tzinfo=timezone.utc)
q=[]
for o in seen.values():
    if o["status"]!="shipped": continue
    dt=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if dt.tzinfo is None: print("NAIVE",o,file=sys.stderr); dt=dt.replace(tzinfo=timezone.utc)
    if lo<=dt.astimezone(timezone.utc)<hi: q.append(o)
cust={}
for o in q:
    c=o["customer_id"]
    if c not in cust:
        cust[c]=get(f"/customers/{c}")
        if cust[c] is None: print("MISSING CUSTOMER",c,file=sys.stderr)
reg=defaultdict(int); tot=0
for o in q:
    c=cust[o["customer_id"]]
    amt=o["amount_cents"]*(100-c["discount_pct"])
    d=(amt*2+100)//200  # half up, exact integer arithmetic
    reg[c["region"]]+=d; tot+=d
res={"total_cents":tot,"order_count":len(q),"duplicates_skipped":dups,
     "by_region":{r:reg.get(r,0) for r in ["north","south","east","west"]}}
print(json.dumps(res),file=sys.stderr)
print("statuses",sorted({o["status"] for o in orders}),"regions",sorted({c["region"] for c in cust.values() if c}),file=sys.stderr)
json.dump(res,open("/workspace/result.json","w"),indent=2)
EOF
cd /tmp/recon && python3 -I run.py

